Lemma unreg_iter_tail : forall (A K odr : Z) (w0 w1 w2 w3 w4 w5 w6 : word)
    (ra gp tp t0 t1 t2 s0 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (sp : word) F fc (m : mem) (o1 o2 o3 o4 o5 : byte),
  ro_cells asegs m A [C8 w0; C8 w1; C8 w2; C8 w3; C8 w4; C8 w5; C8 w6; C8 (Z_to_bv 64 odr)] ->
  rw_cells asegs m 0x7771a0 [C1 o1] -> rw_cells asegs m 0x777140 [C1 o2] -> rw_cells asegs m 0x777141 [C1 o3] -> rw_cells asegs m 0x7771a1 [C1 o4] -> rw_cells asegs m 0x7771a2 [C1 o5] ->
  (odr = ODR_NONE \/ odr = 0x7771a0 \/ odr = 0x777140 \/ odr = 0x777141 \/ odr = 0x7771a1 \/ odr = 0x7771a2) ->
  0x22aa90 <= A -> A + 64 <= 0x2413d0 -> 1 <= K <= 1445 ->
  mem_inv asegs m ->
  evt asegs (fun ms' => exists (ra' s0' t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word) (m' : mem) (o1' o2' o3' o4' o5' : byte),
        ms' = MS (mkR ra' sp gp tp t0' t1' t2' s0' (Z_to_bv 64 0x2d65e8) a0' a1' a2' a3' a4' a5' a6' a7'
                      (Z_to_bv 64 2) (Z_to_bv 64 0x2556f) (Z_to_bv 64 (A + 64)) (Z_to_bv 64 (2^61)) (Z_to_bv 64 0x242330)
                      (Z_to_bv 64 0x227e98) (Z_to_bv 64 0x242370) (Z_to_bv 64 0x2422b8) (Z_to_bv 64 0x244ab8) (Z_to_bv 64 (K - 1))
                      t3' t4' t5' t6')
                 F (Z_to_bv 64 (if K =? 1 then 0xafeec else 0xafce8)) fc None m' (seg_rom asegs)
        /\ munch [(0x7771a0, 0x7771a3); (0x777140, 0x777142)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'
        /\ rw_cells asegs m' 0x7771a0 [C1 o1'] /\ rw_cells asegs m' 0x777140 [C1 o2'] /\ rw_cells asegs m' 0x777141 [C1 o3'] /\ rw_cells asegs m' 0x7771a1 [C1 o4'] /\ rw_cells asegs m' 0x7771a2 [C1 o5'])
    (MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 0x2d65e8) a0 a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 2) (Z_to_bv 64 0x2556f) (Z_to_bv 64 A) (Z_to_bv 64 (2^61)) (Z_to_bv 64 0x242330)
             (Z_to_bv 64 0x227e98) (Z_to_bv 64 0x242370) (Z_to_bv 64 0x2422b8) (Z_to_bv 64 0x244ab8) (Z_to_bv 64 K)
             t3 t4 t5 t6)
        F (Z_to_bv 64 0xafcd0) fc None m (seg_rom asegs)).
Proof.
